To create a **smart scale that tweets applause emojis for each new decimal on the low side**, follow this step-by-step guide:

---

### **Overview**
The scale detects a 0.1 kg weight loss, tweets an applause message, and updates its reference for future decreases. It uses an ESP32, HX711 load cell module, and IFTTT for Twitter integration.

---

### **Hardware Requirements**
1. **ESP32 Dev Module** (or Raspberry Pi Pico W with Wi-Fi)
2. **Load Cell & HX711 Module** (for weight measurement)
3. **Power Source** (LiPo battery or USB)
4. **Jumper Wires & Breadboard**

---

### **Software Setup**
1. **Arduino IDE** (with ESP32 board installed)
2. **IFTTT Account** (for Twitter API access)

---

### **Step 1: Calibrate the Scale**
1. Connect the load cell to the HX711 module.
2. Run the `get_reading()` function to get raw values.
3. Place a known weight (e.g., 5 kg) and calculate the calibration factor:
   ```cpp
   scale.set_scale(calibration_factor); // Adjust this value
   scale.tare(); // Reset scale
   ```

---

### **Step 2: IFTTT Webhook Configuration**
1. Go to [IFTTT Webhooks](https://ifttt.com/maker_webhooks).
2. Create a new applet:
   - **Trigger**: "Webhook" → "Receive a web request".
   - **Event Name**: `weight_loss_tweet`.
   - **Action**: "Twitter" → "Post a tweet".
   - **Tweet Body**:
     ```
     Great job! {{Value1}} 💪 #WeightLossProgress
     ```
3. Copy the webhook URL:  
   `https://maker.ifttt.com/trigger/weight_loss_tweet/with/key/YOUR_IFTTT_KEY`

---

### **Step 3: Code for ESP32**
```cpp
#include <HX711.h>
#include <WiFi.h>
#include <HTTPClient.h>

// WiFi Credentials
const char* ssid = "YOUR_SSID";
const char* password = "YOUR_PASSWORD";

// IFTTT Webhook URL
const char* webhook_url = "https://maker.ifttt.com/trigger/weight_loss_tweet/with/key/YOUR_IFTTT_KEY";

// HX711 Connections
const int LOADCELL_DOUT_PIN = 5;
const int LOADCELL_SCK_PIN = 6;
HX711 scale;

// Calibration Values (Adjust these!)
const long LOADCELL_OFFSET = 0; // From tare()
const float LOADCELL_SCALE = 1; // From calibration

float previous_weight = 0.0;
bool first_read = true;

void setup() {
  Serial.begin(115200);
  scale.begin(LOADCELL_DOUT_PIN, LOADCELL_SCK_PIN);
  scale.set_scale(LOADCELL_SCALE);
  scale.tare();

  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\nWiFi Connected");

  previous_weight = get_weight();
  Serial.print("Initial Weight: ");
  Serial.println(previous_weight);
}

float get_weight() {
  long sum = 0;
  for (int i = 0; i < 10; i++) {
    sum += scale.read();
    delay(100);
  }
  float weight = (sum / 10.0 - LOADCELL_OFFSET) / LOADCELL_SCALE;
  return round(weight * 10) / 10.0; // Rounded to 1 decimal
}

void check_weight() {
  float current_weight = get_weight();
  Serial.print("Current Weight: ");
  Serial.println(current_weight);

  if (first_read) {
    previous_weight = current_weight;
    first_read = false;
    return;
  }

  if (current_weight <= previous_weight - 0.1) {
    Serial.println("Tweeting...");
    tweet_weight(current_weight);
    previous_weight = current_weight;
  }
}

void tweet_weight(float weight) {
  HTTPClient http;
  String message = "New low: " + String(weight, 1) + " kg 👏💪";
  String jsonData = "{\"value1\":\"" + message + "\"}";

  http.begin(webhook_url);
  http.addHeader("Content-Type", "application/json");
  int httpResponseCode = http.POST(jsonData);

  if (httpResponseCode > 0) {
    Serial.print("Tweeted: ");
    Serial.println(message);
  } else {
    Serial.println("Tweet Failed!");
  }
  http.end();
}

